import math

def calculate_area():
    """
    Calculate the area of a rectangle, triangle, or circle based on user input.
    """
    while True:
        shape = input("Enter the shape (rectangle, triangle, or circle): ").lower()

        if shape in ['rectangle', 'triangle', 'circle']:
            break
        else:
            print("Invalid input. Please enter 'rectangle', 'triangle', or 'circle'.")

    while True:
        try:
            length = float(input("Enter the length for a rectangle or triangle: "))
            radius = float(input("Enter the radius for a circle: "))
            break
        except ValueError:
            print("Invalid input. Please enter a number.")

    if shape == 'rectangle':
        area = length * length
    elif shape == 'triangle':
        area = 0.5 * length * radius
    elif shape == 'circle':
        area = math.pi * (radius ** 2)

    print(f"The area is {area}.")

# Call the function
calculate_area()
